--
-- Table structure for table `attack_logs`
--

DROP TABLE IF EXISTS `attack_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attack_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `timestamp` datetime NOT NULL,
  `attack_type` varchar(50) NOT NULL,
  `src_ip` varchar(45) NOT NULL,
  `dst_ip` varchar(45) DEFAULT NULL,
  `src_port` int DEFAULT NULL,
  `dst_port` int DEFAULT NULL,
  `protocol` varchar(10) DEFAULT NULL,
  `severity` varchar(20) NOT NULL,
  `count` int NOT NULL,
  `raw_data` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `hostname` varchar(255) DEFAULT NULL,
  `host_ip` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_attack` (`attack_type`,`src_ip`,`timestamp`),
  KEY `idx_src_ip_timestamp` (`src_ip`,`timestamp`),
  KEY `ix_attack_logs_timestamp` (`timestamp`),
  KEY `ix_attack_logs_src_ip` (`src_ip`),
  KEY `idx_attack_type_timestamp` (`attack_type`,`timestamp`),
  KEY `ix_attack_logs_attack_type` (`attack_type`),
  KEY `idx_hostname_attack_timestamp` (`hostname`,`attack_type`,`timestamp`)
) ENGINE=InnoDB AUTO_INCREMENT=2609 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
